import boto3
from datetime import datetime, timedelta, timezone

def compare_metrics(resource_a, resource_b, metric_name, namespace, stat='Average', period=300, hours_back=24):
    cloudwatch = boto3.client('cloudwatch')
    end_time = datetime.now(timezone.utc)
    start_time = end_time - timedelta(hours=hours_back)

    def get_metric_data(resource_id):
        response = cloudwatch.get_metric_data(
            MetricDataQueries=[
                {
                    'Id': 'm1',
                    'MetricStat': {
                        'Metric': {
                            'Namespace': namespace,
                            'MetricName': metric_name,
                            'Dimensions': [{'Name': 'InstanceId', 'Value': resource_id}]
                        },
                        'Period': period,
                        'Stat': stat
                    },
                    'ReturnData': True
                }
            ],
            StartTime=start_time,
            EndTime=end_time
        )
        return response['MetricDataResults'][0]['Values']

    values_a = get_metric_data(resource_a)
    values_b = get_metric_data(resource_b)

    avg_a = sum(values_a) / len(values_a) if values_a else 0
    avg_b = sum(values_b) / len(values_b) if values_b else 0

    return {
        'resource_a': {'id': resource_a, 'average': avg_a},
        'resource_b': {'id': resource_b, 'average': avg_b},
        'difference': avg_a - avg_b,
        'metric': metric_name,
        'time_window': f'{hours_back}h'
    }
